# ==================================================================== INPUT
# 1. Ask for your three values.
#
#    - the first is TEXT      (a name, a hostname, an IP)  -> no conversion needed
#    - the second is a NUMBER (use float(), not int())
#    - the third  is a NUMBER (use float(), not int())

over_limit_count = 0

while True:
  label = input("Enter a name (or quit):")

  if label.lower()  == "quit":
     break

  value = float(input("Enter the value used:"))
  limit = float(input("Enter the total limit:"))


# ================================================================== PROCESS
# 2. Work out the difference and the percentage.       [Typical and above]

difference = limit - value
percent = (value / limit) * 100

# 3. Decide a status and store it in a variable called status.
#
#    Threshold : if / else        -> "OVER LIMIT" or "OK"
#    Typical   : if / elif / else -> "OVER LIMIT" (100% or more),
#                                     "WARNING" (90% or more), otherwise "OK"

if percent >= 100:
  status = "OVER LIMIT"
elif percent >= 90:
  status = "WARNING"
else:
  status = "OK"

if status == "OVERLIMIT":
  over_limit_counter += 1

# =================================================================== OUTPUT
# 4. Print the report.
#
#    Threshold : the three values you were given, plus status, inside a border
#    Typical   : add difference and percent, 2 decimal places, right-aligned
#    Excellent : wrap sections 1-4 in a loop so you can check as many records
#                as you like in one run - type "quit" as the label to stop.
#                Keep count of how many came back OVER LIMIT and print that
#                once, after the loop ends.

print()
print("=" * 34)
print(f"  RECORD CHECK  -  {label}")
print("=" * 34)

print(f"Used     : {value:8.2f}")
print(f"Total    : {limit:8.2f}")
print(f"Free     : {difference:8.2f}")
print(f"Percent   : {percent:7.2f} %")
print(f"status    : {status}")





print("=" * 34)

print("Records OVER LIMIT:”, over_limit_count")

